// Handle HTTP Response
// If Success, check if there is downlink objet and continue (if any)
// If Error, state the error name

const device = msg.device;
const debug = flow.get("$parent.g_debug");
const dataDirection = env.get("dataDirection");

// === ERROR MESSAGES MAP ===
const ERROR_MESSAGES = {
    400: "Bad HTTP Request",
    401: "Authorization error. Check login and password",
    404: `Invalid URL: '${msg.url}'`,
    EHOSTUNREACH: "Host unreachable. Check IP address",
    ETIMEDOUT: "Connection timeout",
    UNABLE_TO_VERIFY_LEAF_SIGNATURE: "TLS config not enabled in HTTP node"
};

// === HELPER FUNCTIONS ===
function handleError(statusCode, additionalInfo = "") {
    const message = ERROR_MESSAGES[statusCode] || `Unknown error ${statusCode}`;
    node.error(`❌ Error ${statusCode}: ${message}${additionalInfo ? ` - ${additionalInfo}` : ""}`);
    return [null, null];
}

function handleSuccess(device, dataDirection, payload) {
    // Check if payload contains error indicator
    if (payload.includes("Unknown Object")) {
        debug(device, "creation", `${device.identity.deviceName}: Some BACnet objects don't exist`);
        return [{ device }, null];
    }

    switch (dataDirection) {
        case "uplink":
            return handleUplink(device, payload);
        case "downlink":
            return handleDownlink(device, payload);
        default:
            node.error(`Unknown data direction: ${dataDirection}`);
            return [null, null];
    }
}

function handleUplink(device, payload) {
    debug(device, "up", `${device.identity.deviceName} (RestAPI): Write Uplink Objects`);

    const hasDownlinkObjects = Object.values(device.bacnet.objects)
        .some(obj => obj.dataDirection === "downlink");

    if (hasDownlinkObjects) {
        return [null, { device }];  // Continue to read downlink objects
    }

    const txTime = Date.now() - device.transmitTime;
    debug(device, "txTime", `${device.identity.deviceName} (${device.controller.protocol}): TX time = ${txTime}ms`);
    node.warn("------------------------");
    return [null, null];  // Stop here
}

function handleDownlink(device, payload) {
    debug(device, "down", `${device.identity.deviceName} (RestAPI): Read Downlink Objects`);
    return [null, { device, payload: JSON.parse(payload) }];
}

// === MAIN SWITCH ===
switch (msg.statusCode) {
    case 200:
        return handleSuccess(device, dataDirection, msg.payload);

    case 400:
        const additionalInfo = msg.payload.includes("write-access-denied") 
            ? "Trying to write a Read Only object (analogInput)"
            : "";
        return handleError(400, additionalInfo);

    case 401:
    case 404:
    case "EHOSTUNREACH":
    case "ETIMEDOUT":
    case "UNABLE_TO_VERIFY_LEAF_SIGNATURE":
        return handleError(msg.statusCode);

    default:
        node.error(`❌ Unhandled status code: ${msg.statusCode}`);
        return [null, null];
}

// Build the HTTP POST Request for the proper BACnet service
// > Write property if it's the uplink flow
// > Read property if it's the downlink flow

const device = msg.device;
const dataDirection = env.get("dataDirection");

if (dataDirection !== "uplink" && dataDirection !== "downlink") {
    node.error(
        `dataDirection of subflow must be "uplink" or "downlink", got "${dataDirection}"`
    );
    return null;
}

const controller = device?.controller;

if (!controller || controller.protocol !== "restAPIBacnet") {
    return null;
}

switch (controller.model) {

    ///////////////////////////////////////////////////////////
    // Distech Controls V2
    ///////////////////////////////////////////////////////////
    case "distechControlsV2": {
        const bacnetObjects = device?.bacnet?.objects ?? {};
        const propertyReferences = [];

        for (const bacnetObject of Object.values(bacnetObjects)) {

            if (bacnetObject?.dataDirection !== dataDirection) {
                continue;
            }

            const propertyReference = {
                type: bacnetObject.objectType,
                instance: bacnetObject.instanceNum,
                property: "presentValue"
            };

            if (dataDirection === "uplink") {
                propertyReference.value = bacnetObject.value;
            }

            propertyReferences.push(propertyReference);
        }

        const endpoint = dataDirection === "uplink"
            ? "/api/rest/v2/services/bacnet/local/objects/write-property-multiple"
            : "/api/rest/v2/services/bacnet/local/objects/read-property-multiple";

        return {
            method: "POST",
            url: `https://${controller.ipAddress}${endpoint}`,

            headers: {
                Authorization: controller.httpAuthentication,
                ContentType: "application/json"
            },

            payload: {
                encode: "text",
                "property-references": propertyReferences
            },

            requestTimeout: flow.get("$parent.g_httpRequestTimeOut"),

            device
        };
    }

    ///////////////////////////////////////////////////////////
    // Another Controller
    ///////////////////////////////////////////////////////////
    case "anotherController":
        return null;

    ///////////////////////////////////////////////////////////
    // Unknown controller
    ///////////////////////////////////////////////////////////
    default:
        return null;
}

// Build Create Object BACnet service request

const device = msg.device;
const bacnetObjects = device.bacnet.objects;

function buildDistechControlsV2Request(device, bacnetObjects) {
  const requests = Object.values(bacnetObjects).map((obj, index) => ({
    id: String(index + 1),
    method: "POST",
    url: "/api/rest/v2/services/bacnet/local/objects/add",
    body: {
      "object-type": obj.objectType,
      "instance-number": obj.instanceNum,
      name: obj.objectName
    }
  }));

  return {
    method: "POST",
    url: `https://${device.controller.ipAddress}/api/rest/v2/batch`,
    headers: {
      Authorization: device.controller.httpAuthentication,
      ContentType: "application/json"
    },
    payload: { requests },
    requestTimeout: flow.get("$parent.g_httpRequestTimeOut"),
    device
  };
}

switch (device.controller.model) {
  case "distechControlsV2":
    return buildDistechControlsV2Request(device, bacnetObjects);

  case "anotherController":
    node.error("Controller 'anotherController' not yet implemented");
    return null;

  default:
    node.error(`Unknown controller model: ${device.controller.model}`);
    return null;
}

const device = msg.device;
const previousValues = flow.get("$parent.g_previousValues");
const bacnetObjects = device.bacnet.objects;

function buildPropertyReference(object, deviceName, previousValues) {
  let value = object.value;

  if (object.dataDirection === "downlink") {
    const previousValue = previousValues?.[deviceName]?.bacnet.objects[object.objectName]?.value;
    value = previousValue ?? value;
  }

  return {
    type: object.objectType,
    instance: object.instanceNum,
    property: "presentValue",
    value
  };
}

function buildDistechControlsV2Request(device, bacnetObjects, previousValues) {
  return {
    method: "POST",
    url: `https://${device.controller.ipAddress}/api/rest/v2/services/bacnet/local/objects/write-property-multiple`,
    headers: {
      Authorization: device.controller.httpAuthentication,
      ContentType: "application/json"
    },
    payload: {
      encode: "text",
      "property-references": Object.values(bacnetObjects).map(obj => 
        buildPropertyReference(obj, device.identity.deviceName, previousValues)
      )
    },
    requestTimeout: global.get('g_httpRequestTimeOut'),
    device
  };
}

const HANDLERS = {
  distechControlsV2: (device, bacnetObjects, previousValues) => 
    buildDistechControlsV2Request(device, bacnetObjects, previousValues)
};

const handler = HANDLERS[device.controller.model];

if (!handler) {
  throw new Error(`Unknown controller model: ${device.controller.model}`);
}

return handler(device, bacnetObjects, previousValues);

// Handle Success or Error after Objets creation

const device = msg.device;
const debug = flow.get('$parent.g_debug');

const RESPONSE_INDICATORS = {
  SUCCESS: '"status":200',
  ALREADY_EXISTS: ["Instance already exists", "Object with same name already exists"]
};

function handleSuccess(device, payload) {
  if (payload.includes(RESPONSE_INDICATORS.SUCCESS)) {
    debug(device, "creation", `${device.identity.deviceName} (RestAPI): BACnet objects created`);
  }

  if (RESPONSE_INDICATORS.ALREADY_EXISTS.some(msg => payload.includes(msg))) {
    const errorCount = (flow.get('g_errorObjectCreation') || 0) + 1;
    flow.set('g_errorObjectCreation', errorCount);
    node.error(`${device.identity.deviceName}: BACnet objects already exist`);
  }
}

switch (msg.statusCode) {
  case 200:
    handleSuccess(device, msg.payload);
    break;

  default:
    node.error(`Unhandled status code: ${msg.statusCode}`);
}

