const device = msg.device;
const debug = flow.get('$parent.g_debug');
const dataDirection = env.get("dataDirection");
const txTime = Date.now() - device.transmitTime;

debug(device, "txTime", `${device.identity.deviceName} (${device.controller.protocol}): Creation time = ${txTime}ms`);
node.warn("------------------------");

if (dataDirection === "uplink") {
    const hasDownlinkObjects = Object.values(device.bacnet.objects)
        .some(obj => obj.dataDirection === "downlink");

    if (!hasDownlinkObjects) {
        return null;
    }
}

return msg;

/**
 * Stores downlink data received from the controller into the device Object.
 *
 * The function is executed only when dataDirection is "downlink".
 */
const device = msg.device;
const bacnetObjects = device.bacnet.objects;
const dataDirection = env.get("dataDirection");

// Nothing to do for uplink data
if (dataDirection == "uplink") {
    return {
        device: device
    }
}

switch (device.controller.model) {

    case "distechControlsV2": {
        const downlinkObjects = msg.payload;

        for (const result of downlinkObjects.results) {

            Object.values(bacnetObjects).forEach(obj => {

                if (
                    result.type === obj.objectType &&
                    result.instance === obj.instanceNum
                ) {
                    switch (obj.objectType) {

                        case "analogValue":
                            obj.value = Number(result.value);
                            break;

                        case "binaryValue":
                            obj.value = result.value;
                            break;
                    }
                }
            });
        }

        return {
            device: device
        };
    }

    default:
        return {
            device: device
        };
}

/* Prepare downlink */

const device = msg.device;
const bacnetObjects = device.bacnet.objects;
const debug = flow.get("g_debug");
const previousValues = flow.get("g_previousValues") || {};
const previousBacnetObject = previousValues[device.identity.deviceName]?.bacnet?.objects || {};

function isWithinRange(objectDefinition) {
    const range = objectDefinition.range;

    if (!Array.isArray(range) || range.length < 2) {
        return true;
    }

    return objectDefinition.value >= range[0] && objectDefinition.value <= range[1];
}

function shouldTriggerDownlink(objectName, objectDefinition) {
    const previousValue = previousBacnetObject[objectName]?.value;
    const uplinkToCompareWith = objectDefinition.uplinkToCompareWith;
    const uplinkValue = uplinkToCompareWith ? bacnetObjects[uplinkToCompareWith]?.value : undefined;

    switch (objectDefinition.downlinkStrategy) {
        case "onChangeOfThisValue":
            return objectDefinition.value !== previousValue;
        case "onChangeOfThisValueWithinRange":
            return objectDefinition.value !== previousValue && isWithinRange(objectDefinition);
        case "compareToUplinkObjectWithinRange":
            return uplinkValue !== undefined && objectDefinition.value !== uplinkValue && isWithinRange(objectDefinition);
        case "compareToUplinkObject":
            return uplinkValue !== undefined && objectDefinition.value !== uplinkValue;
        default:
            return false;
    }
}

function buildPayloadForObject(objectName) {
    const downlinkPort = bacnetObjects[objectName].downlinkPort;
    const payload = {};

    Object.keys(bacnetObjects).forEach((candidateName) => {
        const candidate = bacnetObjects[candidateName];

        if (candidate.dataDirection === "downlink" && candidate.downlinkPort === downlinkPort) {
            payload[candidateName] = candidate.value;
        }
    });

    return { downlinkPort, payload };
}

function buildDownlinkDebugMessage(objectName, objectDefinition) {
    const previousValue = previousBacnetObject[objectName]?.value;
    const sourceName = objectDefinition.uplinkToCompareWith;
    const sourceValue = sourceName ? bacnetObjects[sourceName]?.value : undefined;
    const base = `${device.identity.deviceName} (${device.controller.protocol}) : Downlink scheduled : `;

    switch (objectDefinition.downlinkStrategy) {
        case "onChangeOfThisValue":
            return `${base}${objectName} ${objectDefinition.value} ≠ previous value`;
        case "onChangeOfThisValueWithinRange":
            return `${base}${objectName} ${previousValue} ≠ previous value and out of range`;
        case "compareToUplinkObjectWithinRange":
            return `${base}${sourceName} ${sourceValue} ≠ ${objectName} ${objectDefinition.value} and out of range`;
        case "compareToUplinkObject":
            return `${base}${sourceName} ${sourceValue} ≠ ${objectName} ${objectDefinition.value}`;
        default:
            return `${base}${objectName} ${objectDefinition.value}`;
    }
}

function updatePreviousValues(payload) {
    Object.keys(payload).forEach((objectName) => {
        if (previousBacnetObject[objectName]) {
            previousBacnetObject[objectName].value = payload[objectName];
        }
    });
}

let downlinkLowPriorityObject = null;
let finalPayload = {};
let downlinkPort = null;

for (const objectName in bacnetObjects) {
    const objectDefinition = bacnetObjects[objectName];

    if (objectDefinition.dataDirection !== "downlink") {
        continue;
    }

    if (objectDefinition.downlinkPortPriority === "high" && shouldTriggerDownlink(objectName, objectDefinition)) {
        const result = buildPayloadForObject(objectName);

        node.status({ fill: "yellow", shape: "dot", text: `Downlink ${device.identity.deviceName}` });
        debug(device, "down", buildDownlinkDebugMessage(objectName, objectDefinition));

        finalPayload = result.payload;
        downlinkPort = result.downlinkPort;
        msg.device.lorawan.downlinkPort = downlinkPort;
        break;
    }

    if (objectDefinition.downlinkPortPriority === "low" && shouldTriggerDownlink(objectName, objectDefinition)) {
        downlinkLowPriorityObject = objectName;
    }
}

if (Object.keys(finalPayload).length === 0 && downlinkLowPriorityObject !== null) {
    const result = buildPayloadForObject(downlinkLowPriorityObject);

    node.status({ fill: "yellow", shape: "dot", text: `Downlink ${device.identity.deviceName}` });
    debug(device, "down", buildDownlinkDebugMessage(downlinkLowPriorityObject, bacnetObjects[downlinkLowPriorityObject]));

    finalPayload = result.payload;
    downlinkPort = result.downlinkPort;
    msg.device.lorawan.downlinkPort = downlinkPort;
}

if (Object.keys(finalPayload).length === 0) {
    node.status({ fill: "green", shape: "dot", text: "No downlink" });
    return null;
}

updatePreviousValues(finalPayload);

const remappedPayload = {};
Object.keys(finalPayload).forEach((objectName) => {
    const lorawanPayloadName = bacnetObjects[objectName].lorawanPayloadName || objectName;
    remappedPayload[lorawanPayloadName] = finalPayload[objectName];
});

let downlinkJson = {};

if (device.lorawan.networkServer === "tts") {
    downlinkJson = {
        topic: device.mqtt.topicDownlink + (device.lorawan.flushDownlinkQueue ? "/replace" : "/push"),
        payload: {
            downlinks: [
                {
                    f_port: downlinkPort,
                    decoded_payload: remappedPayload,
                    priority: "NORMAL"
                }
            ]
        }
    };
    debug(device, "txTime", `${device.identity.deviceName} (${device.controller.protocol}) : TX time = ${Date.now() - device.transmitTime} ms`);
    node.warn("------------------------");
    return downlinkJson;
}

if (device.lorawan.networkServer === "chirpstack") {
    if (device.lorawan.flushDownlinkQueue === true) {
        debug(device, "downlink", `${device.identity.deviceName} flush downlink queue`);

        const grpc = grpcJs;
        const deviceGrpc = chirpstack_device_grpc;
        const devicePb = chirpstack_device_pb;
        const server = `${device.lorawan.chirpstack.serverAddress}:${device.lorawan.chirpstack.grpcPort}`;
        const devEui = device.identity.devEUI;
        const apiToken = device.lorawan.chirpstack.grpcApiKey;
        const deviceService = new deviceGrpc.DeviceServiceClient(server, grpc.credentials.createInsecure());
        const metadata = new grpc.Metadata();

        metadata.set("authorization", `Bearer ${apiToken}`);

        const flushReq = new devicePb.FlushDeviceQueueRequest();
        flushReq.setDevEui(devEui);

        deviceService.flushQueue(flushReq, metadata, (err) => {
            if (err !== null) {
                node.error(`Can't flush ChirpStack downlink queue : ${err}`);
            }
        });
    }

    downlinkJson = {
        topic: device.mqtt.topicDownlink,
        payload: {
            devEui: device.identity.devEUI,
            confirmed: false,
            fPort: downlinkPort,
            object: remappedPayload
        }
    };
    debug(device, "txTime", `${device.identity.deviceName} (${device.controller.protocol}) : TX time = ${Date.now() - device.transmitTime} ms`);
    node.warn("------------------------");
    return downlinkJson;
}

if (device.lorawan.networkServer === "actility") {
    downlinkJson = {
        topic: device.mqtt.topicDownlink,
        payload: {
            DevEUI_downlink: {
                DevEUI: device.identity.devEUI,
                FPort: downlinkPort,
                payload: remappedPayload,
                FlushDownlinkQueue: String(+device.lorawan.flushDownlinkQueue),
                DriverCfg: {
                    app: {
                        pId: device.lorawan.actility.driver.pId,
                        mId: device.lorawan.actility.driver.mId,
                        ver: device.lorawan.actility.driver.ver
                    }
                }
            }
        }
    };
    debug(device, "txTime", `${device.identity.deviceName} (${device.controller.protocol}) : TX time = ${Date.now() - device.transmitTime} ms`);
    node.warn("------------------------");
    return downlinkJson;
}

return null;

const client = new nodeBacnet();
const device = msg.device;
const debug = flow.get("g_debug");
const bacnetObjects = device?.bacnet?.objects || {};

msg.payload = [];

if (device?.controller?.protocol !== "bacnet") {
  return null;
}

const uplinkObjects = Object.entries(bacnetObjects).filter(([, objectDefinition]) => objectDefinition.dataDirection === "uplink");

return Promise.all(
  uplinkObjects.map(([objectName, objectDefinition]) => {
    const objectId = {
      type: objectDefinition.objectType,
      instance: objectDefinition.instanceNum
    };

    const valueToWrite = [{
      type: objectDefinition.objectType === 2 ? 4 : 0,
      value: objectDefinition.value
    }];

    return new Promise((resolve, reject) => {
      client.writeProperty(device.controller.ipAddress, objectId, 85, valueToWrite, (err, value) => {
        if (err) {
          const errorMessage = `Error writing BACnet object ${objectName}: ${err}`;
          node.status({ fill: "red", shape: "dot", text: `BACnet ${err}` });
          node.error(errorMessage, {
            errorType: "nativeBACnet",
            error: err
          });
          reject(err);
          return;
        }

        msg.payload.push(value);
        debug(device, "up", `${device.identity.deviceName} (${device.controller.protocol}) : Write Uplink Objects - ${objectName}`);
        resolve();
      });
    });
  })
)
  .then(() => {
    node.status({ fill: "green", shape: "dot", text: "Native BACnet" });
    return msg;
  })
  .catch((err) => {
    node.error(err);
    return null;
  });

const client = new nodeBacnet();
const device = msg.device;
const bacnetObjects = device?.bacnet?.objects || {};
const debug = flow.get("g_debug");

if (device?.controller?.protocol !== "bacnet") {
  return null;
}

const requestArray = Object.values(bacnetObjects)
  .filter((objectDefinition) => objectDefinition.dataDirection === "downlink")
  .map((objectDefinition) => ({
    objectId: {
      type: objectDefinition.objectType,
      instance: objectDefinition.instanceNum
    },
    properties: [{ id: 85 }]
  }));

return new Promise((resolve, reject) => {
  client.readPropertyMultiple(device.controller.ipAddress, requestArray, (err, value) => {
    if (err) {
      node.status({ fill: "red", shape: "dot", text: `BACnet ${err}` });
      node.error(err);
      reject(err);
      return;
    }

    if (!value) {
      resolve(null);
      return;
    }

    msg.payload = value;
    debug(device, "down", `${device.identity.deviceName} (${device.controller.protocol}) : Read downlink Objects`);
    resolve(msg);
  });
})
  .then((message) => {
    if (!message || !message.payload || !Array.isArray(message.payload.values)) {
      return { device };
    }

    const values = message.payload.values;

    values.forEach((readValue) => {
      const matchingObject = Object.values(bacnetObjects).find((objectDefinition) => {
        return readValue.objectId.type == objectDefinition.objectType && readValue.objectId.instance == objectDefinition.instanceNum;
      });

      if (!matchingObject || !Array.isArray(readValue.values) || !Array.isArray(readValue.values[0]?.value)) {
        return;
      }

      matchingObject.value = readValue.values[0].value[0].value;
    });

    node.status({ fill: "green", shape: "dot", text: "Native BACnet" });
    return { device };
  })
  .catch((err) => {
    node.status({ fill: "red", shape: "dot", text: err });
    node.error("Error reading bacnet objects", {
      errorType: "nativeBACnet",
      error: err
    });
    return null;
  });
